@OptIn(ExperimentalMaterial3Api::class)
@Composable fun ProgressScreen(data:ProgressUiData){val history=data.history;val stats=data.keyStats;val transitions=data.weakTransitions;val profile=data.profile;var metric by remember{mutableStateOf(ChartMetric.WPM)};var selectedKey by remember{mutableStateOf<Char?>(null)};val values=when(metric){ChartMetric.WPM->history.map{it.wpm};ChartMetric.ACCURACY->history.map{it.accuracy};ChartMetric.SCORE->history.map{it.thumbScore}};val delta=if(history.size>=2)history.last().wpm-history.first().wpm else 0
 LazyColumn(Modifier.fillMaxSize(),contentPadding=PaddingValues(20.dp),verticalArrangement=Arrangement.spacedBy(15.dp)){item{AppPageHeader("Progress","See speed, accuracy, weak keys, transitions and achievements in one place.")};item{Row(horizontalArrangement=Arrangement.spacedBy(9.dp)){MetricCard("${data.lastWpm}","Current WPM",Icons.Default.Speed,Modifier.weight(1f));MetricCard("${data.bestWpm}","Best WPM",Icons.Default.EmojiEvents,Modifier.weight(1f),ThumbAmber);MetricCard("${data.thumbScore}","ThumbScore",Icons.Default.AutoGraph,Modifier.weight(1f),MaterialTheme.colorScheme.secondary)}};item{PremiumCard{Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Column{Text("Performance trend",style=MaterialTheme.typography.titleLarge);Text("${history.size} recent sessions",fontSize=12.sp,color=MaterialTheme.colorScheme.onSurfaceVariant)};if(history.size>=2&&metric==ChartMetric.WPM)TinyPill("${if(delta>=0)"+" else ""}$delta WPM",Icons.Default.TrendingUp,MaterialTheme.colorScheme.secondary)};Spacer(Modifier.height(12.dp));SingleChoiceSegmentedButtonRow(Modifier.fillMaxWidth()){ChartMetric.entries.forEachIndexed{i,m->SegmentedButton(selected=metric==m,onClick={metric=m},shape=SegmentedButtonDefaults.itemShape(i,ChartMetric.entries.size)){Text(when(m){ChartMetric.WPM->"WPM";ChartMetric.ACCURACY->"Accuracy";ChartMetric.SCORE->"Score"},fontSize=11.sp)}}};Spacer(Modifier.height(12.dp));ProgressChart(values.ifEmpty{listOf(0,0)})}};item{PremiumCard{Text("Baseline comparison",style=MaterialTheme.typography.titleMedium);Spacer(Modifier.height(10.dp));DetailLine("Starting speed",if(profile.baselineWpm>0)"${profile.baselineWpm} WPM" else "Not measured");DetailLine("Current speed","${data.lastWpm} WPM");DetailLine("Target","${profile.targetWpm} WPM @ ${profile.targetAccuracy}%")}};item{KeyboardHeatmap(stats){selectedKey=it}};item{SectionHeading("Weak transitions")};if(transitions.isEmpty())item{PremiumCard{Text("Complete more practice and ThumbType will identify slow or error-prone key pairs.",color=MaterialTheme.colorScheme.onSurfaceVariant)}}else items(transitions){(pair,s)->PremiumCard{Row(verticalAlignment=Alignment.CenterVertically){Surface(shape=RoundedCornerShape(12.dp),color=MaterialTheme.colorScheme.error.copy(.10f)){Text(pair.uppercase(),Modifier.padding(horizontal=12.dp,vertical=8.dp),fontWeight=FontWeight.Black,color=MaterialTheme.colorScheme.error)};Spacer(Modifier.width(13.dp));Column(Modifier.weight(1f)){Text("${s.averageMs} ms average",fontWeight=FontWeight.Bold);Text("${s.errors} errors • ${s.accuracy}% accuracy",fontSize=12.sp,color=MaterialTheme.colorScheme.onSurfaceVariant)}}}};item{SectionHeading("Achievements")};item{Column(verticalArrangement=Arrangement.spacedBy(9.dp)){data.achievements.chunked(2).forEach{row->Row(horizontalArrangement=Arrangement.spacedBy(9.dp)){row.forEach{(t,u)->AchievementChip(t,u,Modifier.weight(1f))};if(row.size==1)Spacer(Modifier.weight(1f))}}}};item{Spacer(Modifier.height(8.dp))}}
 selectedKey?.let{KeyDetailDialog(it,stats[it]?:KeyAggregate()){selectedKey=null}}
}

