@Composable fun PrivacyScreen(onBack:()->Unit,onExport:()->Unit,onImport:()->Unit,onDeleteAll:()->Unit){var confirm by remember{mutableStateOf(false)};LazyColumn(Modifier.fillMaxSize(),contentPadding=PaddingValues(20.dp),verticalArrangement=Arrangement.spacedBy(13.dp)){item{Row(verticalAlignment=Alignment.CenterVertically){IconButton(onClick=onBack){Icon(Icons.Default.ArrowBack,"Back")};Column{Text("Privacy & data",style=MaterialTheme.typography.headlineMedium);Text("Your typing practice should remain yours.",color=MaterialTheme.colorScheme.onSurfaceVariant)}}};item{GradientHero("Security posture","Local by default","Core lessons and analytics work without an account."){Icon(Icons.Default.Shield,null,Modifier.align(Alignment.CenterEnd).size(56.dp),tint=Color.White.copy(.9f))}};item{PremiumCard{Text("Stored locally",style=MaterialTheme.typography.titleMedium);Spacer(Modifier.height(9.dp));PrivacyLine(Icons.Default.Speed,"Performance","WPM, accuracy, scores and session summaries");PrivacyLine(Icons.Default.Keyboard,"Technique","Aggregated key and transition statistics");PrivacyLine(Icons.Default.EmojiEvents,"Progress","XP, streaks and completed lessons");PrivacyLine(Icons.Default.Tune,"Preferences","Goals, theme and coach settings")}};item{PremiumCard{Text("Not requested",style=MaterialTheme.typography.titleMedium);Spacer(Modifier.height(8.dp));listOf("Internet access","Location","Contacts","Camera","Microphone","Broad storage permission").forEach{Row(Modifier.padding(vertical=4.dp),verticalAlignment=Alignment.CenterVertically){Icon(Icons.Default.CheckCircle,null,Modifier.size(18.dp),tint=MaterialTheme.colorScheme.secondary);Spacer(Modifier.width(9.dp));Text(it)}}}};item{Surface(shape=RoundedCornerShape(20.dp),color=MaterialTheme.colorScheme.primaryContainer){Row(Modifier.padding(16.dp)){Icon(Icons.Default.Info,null,tint=MaterialTheme.colorScheme.primary);Spacer(Modifier.width(11.dp));Text("Touch-side analysis uses screen position. It does not claim to identify your biological thumb from Android touch data.",style=MaterialTheme.typography.bodyMedium)}}};item{SectionHeading("Your controls")};item{ActionRow("Export backup","Create a user-requested JSON backup",Icons.Default.FileUpload,onClick=onExport)};item{ActionRow("Restore backup","Import a ThumbType backup you choose",Icons.Default.Restore,MaterialTheme.colorScheme.secondary,onClick=onImport)};item{Surface(Modifier.fillMaxWidth().clickable{confirm=true},shape=RoundedCornerShape(20.dp),color=MaterialTheme.colorScheme.errorContainer){Row(Modifier.padding(16.dp),verticalAlignment=Alignment.CenterVertically){Icon(Icons.Default.DeleteForever,null,tint=MaterialTheme.colorScheme.error);Spacer(Modifier.width(12.dp));Column(Modifier.weight(1f)){Text("Delete all local data",fontWeight=FontWeight.Bold,color=MaterialTheme.colorScheme.error);Text("Reset this device",fontSize=12.sp)}}}};item{PremiumCard{Text("Production security",style=MaterialTheme.typography.titleMedium);Text("R8 hardening, no cleartext traffic, app-data backup disabled, private FileProvider exports, and no hard-coded signing password.",color=MaterialTheme.colorScheme.onSurfaceVariant)}}};if(confirm)AlertDialog(onDismissRequest={confirm=false},icon={Icon(Icons.Default.Warning,null,tint=MaterialTheme.colorScheme.error)},title={Text("Delete all ThumbType data?")},text={Text("This removes local profile, settings, progress and analytics. Export first if needed.")},confirmButton={TextButton(onClick={confirm=false;onDeleteAll()}){Text("Delete",color=MaterialTheme.colorScheme.error)}},dismissButton={TextButton(onClick={confirm=false}){Text("Cancel")}})}
@Composable private fun PrivacyLine(icon:androidx.compose.ui.graphics.vector.ImageVector,title:String,subtitle:String){Row(Modifier.padding(vertical=6.dp),verticalAlignment=Alignment.Top){Icon(icon,null,Modifier.size(20.dp),tint=MaterialTheme.colorScheme.primary);Spacer(Modifier.width(11.dp));Column{Text(title,fontWeight=FontWeight.Bold);Text(subtitle,fontSize=12.sp,color=MaterialTheme.colorScheme.onSurfaceVariant)}}}

@Composable fun ResultsScreen(result:SessionResult,profile:UserProfile,personalBest:Int,onContinue:()->Unit,onRetry:()->Unit,onWeakness:()->Unit){val insight=TrainingEngine.coachingInsight(result,profile.targetAccuracy);LazyColumn(Modifier.fillMaxSize(),contentPadding=PaddingValues(22.dp),horizontalAlignment=Alignment.CenterHorizontally,verticalArrangement=Arrangement.spacedBy(15.dp)){item{Surface(shape=CircleShape,color=MaterialTheme.colorScheme.secondary.copy(.13f)){Icon(Icons.Default.EmojiEvents,null,Modifier.padding(18.dp).size(36.dp),tint=MaterialTheme.colorScheme.secondary)};Spacer(Modifier.height(10.dp));Text("Session complete",style=MaterialTheme.typography.headlineLarge,textAlign=TextAlign.Center);Text(result.title,color=MaterialTheme.colorScheme.onSurfaceVariant)};item{Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically,horizontalArrangement=Arrangement.SpaceEvenly){ScoreRing(result.thumbScore);Column{Text("${result.netWpm}",fontSize=44.sp,fontWeight=FontWeight.Black,color=MaterialTheme.colorScheme.primary);Text("NET WPM",fontSize=10.sp,fontWeight=FontWeight.Black);if(result.netWpm>=personalBest)TinyPill("Personal best",Icons.Default.EmojiEvents,ThumbAmber)}}};item{PremiumCard{Text("Performance",style=MaterialTheme.typography.titleMedium);Spacer(Modifier.height(12.dp));PercentBar("Accuracy",result.accuracy,MaterialTheme.colorScheme.secondary);Spacer(Modifier.height(10.dp));PercentBar("Rhythm",result.rhythm,ThumbAmber);Spacer(Modifier.height(10.dp));PercentBar("Consistency",result.consistency);Spacer(Modifier.height(10.dp));PercentBar("Reach-match",result.thumbTechnique,MaterialTheme.colorScheme.secondary);Spacer(Modifier.height(12.dp));DetailLine("Raw WPM","${result.rawWpm}");DetailLine("Attempts","${result.attempts}");DetailLine("Mistakes","${result.mistakes}");DetailLine("Recovered mistakes","${result.correctedErrors}");DetailLine("Unresolved mistakes","${result.uncorrectedErrors}");DetailLine("Correct characters","${result.chars}")}};item{Surface(shape=RoundedCornerShape(21.dp),color=MaterialTheme.colorScheme.primaryContainer){Row(Modifier.padding(16.dp)){Icon(Icons.Default.Psychology,null,tint=MaterialTheme.colorScheme.primary);Spacer(Modifier.width(11.dp));Column{Text("Coach insight",fontWeight=FontWeight.Bold);Text(insight,style=MaterialTheme.typography.bodyMedium)}}}};if(result.weakKey!=null||result.weakTransition!=null)item{PremiumCard{Text("Next improvement target",style=MaterialTheme.typography.titleMedium);result.weakKey?.let{DetailLine("Weak key",it.uppercase())};result.weakTransition?.let{DetailLine("Weak transition",it.uppercase())};DetailLine("Touch balance","L ${result.leftTouches} • R ${result.rightTouches}")}};item{Button(onClick=onContinue,Modifier.fillMaxWidth().height(54.dp),shape=RoundedCornerShape(17.dp)){Text("Continue",fontWeight=FontWeight.Bold)};Spacer(Modifier.height(8.dp));Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){OutlinedButton(onClick=onRetry,Modifier.weight(1f)){Icon(Icons.Default.Replay,null);Text(" Retry")};OutlinedButton(onClick=onWeakness,Modifier.weight(1f)){Icon(Icons.Default.AutoFixHigh,null);Text(" Weakness")}}}}}
